1	use alloy::primitives::{Address, U256};
2	use alloy::providers::{Provider, DynProvider};
3	use alloy::network::Ethereum;
4	use tracing::info;
5	use crate::contracts::{IVeaOutbox, IWETH, IOutbox, IRollup};
6	use crate::config::{ValidatorConfig, Route, RouteSettings};
7	use crate::RECEIPT_TIMEOUT;
8	
9	pub fn check_finality_config(config: &ValidatorConfig) {
10	    if config.sequencer_inbox.is_none() {
11	        panic!("FATAL: SEQUENCER_INBOX must be set for L2 finality verification");
12	    }
13	    info!(logger = "Startup", sequencer_inbox = ?config.sequencer_inbox.unwrap(), "Finality config OK");
14	}
15	
16	const TIMING_SAFETY_BUFFER_SECS: u64 = 10 * 60;
17	
18	pub async fn check_rpc_health(routes: &[Route]) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
19	    info!(logger = "Startup", "Checking RPC endpoint health");
20	
21	    let arb_provider = &routes[0].inbox_provider;
22	    let eth_provider = &routes[0].outbox_provider;
23	    let gnosis_provider = &routes[1].outbox_provider;
24	
25	    let arb_block = crate::retry_rpc("check Arbitrum RPC health", || async { arb_provider.get_block_number().await }).await
26	        .map_err(|e| format!("FATAL: Arbitrum RPC unreachable or unhealthy: {e}"))?;
27	    info!(logger = "Startup", chain = "Arbitrum", block = arb_block, "RPC healthy");
28	    let eth_block = crate::retry_rpc("check Ethereum RPC health", || async { eth_provider.get_block_number().await }).await
29	        .map_err(|e| format!("FATAL: Ethereum RPC unreachable or unhealthy: {e}"))?;
30	    info!(logger = "Startup", chain = "Ethereum", block = eth_block, "RPC healthy");
31	    let gnosis_block = crate::retry_rpc("check Gnosis RPC health", || async { gnosis_provider.get_block_number().await }).await
32	        .map_err(|e| format!("FATAL: Gnosis RPC unreachable or unhealthy: {e}"))?;
33	    info!(logger = "Startup", chain = "Gnosis", block = gnosis_block, "RPC healthy");
34	    Ok(())
35	}
36	
37	pub async fn check_balances(c: &ValidatorConfig, routes: &[Route]) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
38	    let wallet_address = c.wallet.default_signer().address();
39	    let eth_provider = routes[0].outbox_provider.clone();
40	    let gnosis_provider = routes[1].outbox_provider.clone();
41	
42	    let eth_outbox = IVeaOutbox::new(c.outbox_arb_to_eth, eth_provider.clone());
43	    let gnosis_outbox = IVeaOutbox::new(c.outbox_arb_to_gnosis, gnosis_provider.clone());
44	
45	    let eth_deposit = eth_outbox.deposit().call().await?;
46	    let eth_balance = eth_provider.get_balance(wallet_address).await?;
47	    if eth_balance < eth_deposit {
48	        panic!("FATAL: Insufficient ETH balance. Need {} wei for deposit, have {} wei", eth_deposit, eth_balance);
49	    }
50	
51	    let gnosis_deposit = gnosis_outbox.deposit().call().await?;
52	    let weth_addr = c.chains.get(&100).expect("Gnosis").deposit_token
53	        .expect("Gnosis should use WETH");
54	    let weth = IWETH::new(weth_addr, gnosis_provider.clone());
55	    let weth_balance = weth.balanceOf(wallet_address).call().await?;
56	    if weth_balance < gnosis_deposit {
57	        panic!("FATAL: Insufficient WETH balance on Gnosis. Need {} wei for deposit, have {} wei", gnosis_deposit, weth_balance);
58	    }
59	
60	    let xdai_balance = gnosis_provider.get_balance(wallet_address).await?;
61	    let xdai_min = U256::from(10_000_000_000_000_000u64);
62	    if xdai_balance < xdai_min {
63	        panic!("FATAL: Insufficient xDAI on Gnosis for gas. Need {} wei, have {} wei", xdai_min, xdai_balance);
64	    }
65	    info!(logger = "Startup", eth = %eth_balance, weth = %weth_balance, xdai = %xdai_balance, "Balance check passed");
66	
67	    ensure_weth_approval(c, gnosis_provider, wallet_address).await?;
68	
69	    Ok(())
70	}
71	
72	pub async fn ensure_weth_approval(c: &ValidatorConfig, gnosis_provider: DynProvider<Ethereum>, wallet_address: alloy::primitives::Address) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
73	    let weth_addr = c.chains.get(&100).expect("Gnosis").deposit_token
74	        .expect("Gnosis should use WETH");
75	    let weth = IWETH::new(weth_addr, gnosis_provider);
76	    let current_allowance = weth.allowance(wallet_address, c.outbox_arb_to_gnosis).call().await?;
77	
78	    if current_allowance == U256::ZERO {
79	        info!(logger = "Startup", "No WETH approval found for Gnosis outbox, setting max approval");
80	        let max_approval = U256::MAX;
81	        let approve_tx = weth.approve(c.outbox_arb_to_gnosis, max_approval);
82	        let pending = approve_tx.send().await?;
83	        let receipt = pending.with_timeout(Some(RECEIPT_TIMEOUT)).get_receipt().await?;
84	
85	        if !receipt.status() {
86	            panic!("FATAL: WETH approval transaction failed");
87	        }
88	
89	        info!(logger = "Startup", "WETH max approval set for Gnosis outbox");
90	    } else {
91	        info!(logger = "Startup", allowance = %current_allowance, "WETH approval exists");
92	    }
93	
94	    Ok(())
95	}
96	
97	/// How far back to sample when measuring average block time. On chains shorter
98	/// than this the lookback is clamped to genesis and the divisor follows the
99	/// actual block delta, so the average stays correct instead of being skewed.
