5	use alloy::rpc::json_rpc::{RequestPacket, ResponsePacket, ResponsePayload};
6	use alloy::transports::http::Http;
7	use alloy::transports::layers::FallbackLayer;
8	use alloy::transports::{TransportError, TransportErrorKind, TransportFut};
9	use std::num::NonZeroUsize;
10	use std::str::FromStr;
11	use std::task::{Context, Poll};
12	use std::time::Duration;
13	use std::collections::HashMap;
14	use tower::{Service, ServiceBuilder};
15	use tracing::warn;
16	
17	const RPC_TIMEOUT: Duration = Duration::from_secs(30);
18	
19	/// Returns `true` for JSON-RPC error responses that indicate the endpoint itself is
20	/// broken (misconfigured, unauthorized, rate-limited, overloaded) rather than an
21	/// application-level error (e.g. a contract revert).
22	///
23	/// alloy's `FallbackLayer` only fails over on transport-level errors (connection
24	/// refused, timeout, HTTP 5xx); a JSON-RPC error delivered over a valid HTTP 200
25	/// response is otherwise treated as a "successful" call, so a misconfigured endpoint
26	/// that responds quickly with an auth error can win the fallback race indefinitely
27	/// and never gets scored down. `ErrorAwareTransport` below reclassifies these specific
28	/// cases as transport errors so the fallback logic actually routes around them.
29	fn is_infra_rpc_error(code: i64, message: &str) -> bool {
30	    // -32000 ("server error") is deliberately excluded from this code-only match: it's a
31	    // broad, provider-defined catch-all that some nodes also use for application-level
32	    // reverts (with a `data` payload we must not discard). Its auth/rate-limit cases are
33	    // still caught below via message text, which is unambiguous.
34	    matches!(code, -32603 | -32005)
35	        || message.contains("Unauthorized")
36	        || message.contains("API key")
37	        || message.contains("api key")
38	        || message.contains("rate limit")
39	        || message.contains("Too Many Requests")
40	}
41	
42	/// Wraps an RPC transport so JSON-RPC responses matching [`is_infra_rpc_error`] are
43	/// surfaced as transport errors instead of being passed through as a successful call.
44	#[derive(Clone)]
45	struct ErrorAwareTransport<S> {
46	    inner: S,
47	    label: String,
48	}
49	
50	impl<S> Service<RequestPacket> for ErrorAwareTransport<S>
51	where
52	    S: Service<RequestPacket, Response = ResponsePacket, Error = TransportError, Future = TransportFut<'static>>
53	        + Send
54	        + Clone
55	        + 'static,
56	{
57	    type Response = ResponsePacket;
58	    type Error = TransportError;
59	    type Future = TransportFut<'static>;
60	
61	    fn poll_ready(&mut self, cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
62	        self.inner.poll_ready(cx)
63	    }
64	
65	    fn call(&mut self, req: RequestPacket) -> Self::Future {
66	        let label = self.label.clone();
67	        let fut = self.inner.call(req);
68	        Box::pin(async move {
69	            let response = fut.await?;
70	
71	            let infra_error = match &response {
72	                ResponsePacket::Single(r) => match &r.payload {
73	                    ResponsePayload::Failure(e) if is_infra_rpc_error(e.code, &e.message) => {
74	                        Some(format!("error code {}: {}", e.code, e.message))
75	                    }
76	                    _ => None,
77	                },
78	                ResponsePacket::Batch(rs) => rs.iter().find_map(|r| match &r.payload {
79	                    ResponsePayload::Failure(e) if is_infra_rpc_error(e.code, &e.message) => {
80	                        Some(format!("error code {}: {}", e.code, e.message))
81	                    }
82	                    _ => None,
83	                }),
84	            };
85	
86	            if let Some(msg) = infra_error {
87	                warn!(logger = "Config", transport = label.as_str(), "RPC endpoint returned infra-level error, treating as unavailable for fallback purposes: {msg}");
88	                return Err(TransportErrorKind::custom_str(&msg));
89	            }
90	
91	            Ok(response)
92	        })
93	    }
94	}
