177	fn build_provider_from_urls(urls: &[String], wallet: &EthereumWallet) -> DynProvider<Ethereum> {
178	    let http_client = build_http_client();
179	
180	    if urls.len() == 1 {
181	        let transport = Http::with_client(http_client, urls[0].parse().expect("Invalid RPC URL"));
182	        let client = RpcClient::builder().transport(transport, false);
183	        return DynProvider::new(
184	            ProviderBuilder::new()
185	                .wallet(wallet.clone())
186	                .connect_client(client)
187	        );
188	    }
189	
190	    let fallback = FallbackLayer::default()
191	        .with_active_transport_count(NonZeroUsize::new(3).unwrap());
192	
193	    let transports: Vec<_> = urls.iter()
194	        .map(|url| ErrorAwareTransport {
195	            inner: Http::with_client(http_client.clone(), url.parse().expect("Invalid RPC URL")),
196	            label: redact_url(url),
197	        })
198	        .collect();
199	
200	    let transport = ServiceBuilder::new()
201	        .layer(fallback)
202	        .service(transports);
203	
204	    let client = RpcClient::builder().transport(transport, false);
205	    DynProvider::new(
206	        ProviderBuilder::new()
207	            .wallet(wallet.clone())
208	            .connect_client(client)
209	    )
210	}
